WITH incoming AS (
  SELECT * FROM jsonb_to_recordset($companies$[{"company_id":"bmo-capital-markets","name":"BMO Capital Markets","company_type":"Investment Bank","headquarters_country":null,"status":"active"},{"company_id":"kpmg-cf","name":"KPMG Corporate Finance","company_type":"Investment Bank","headquarters_country":null,"status":"active"},{"company_id":"aimco","name":"AIMCo","company_type":"Institutional Investor","headquarters_country":null,"status":"active"}]$companies$::jsonb)
  AS company(company_id text, name text, company_type text, headquarters_country text, status text)
)
INSERT INTO public.companies (company_id, name, company_type, headquarters_country, status, updated_at)
SELECT company_id, name, company_type, headquarters_country, status, now()
FROM incoming
ON CONFLICT DO NOTHING;

WITH incoming AS (
  SELECT * FROM jsonb_to_recordset($jobs$[{"external_job_id":"R260028848","company_id":"bmo-capital-markets","company_name":"BMO Capital Markets","title":"BMO Capital Markets Investment Banking Summer 2027 Sophomore Analyst, Infrastructure Debt Capital Markets, Toronto","location_display":"Toronto, ON","city":"Toronto","province":"ON","country":"Canada","workplace_type":null,"category":"Investment Banking","specialization":"Debt Capital Markets","seniority":"Analyst","employment_type":"Contract","program_type":"Internship","term_start":null,"term_end":null,"term_length_months":null,"date_posted":"2026-10-13","application_deadline":null,"salary_min":95000,"salary_max":null,"salary_currency":"CAD","salary_period":"year","application_url":"https://bmo.wd3.myworkdayjobs.com/External/job/Toronto-ON-CAN/BMO-Capital-Markets-Summer-2027-Sophomore-Analyst--Toronto_R260028848/apply","source_url":"https://jobs.bmo.com/ca/en/job/BOMOGLOBALR260028848EXTERNALENCA/BMO-Capital-Markets-Investment-Banking-Summer-2027-Sophomore-Analyst-Infrastructure-Debt-Capital-Markets-Toronto","source_name":"BMO Capital Markets public careers site","status":"active","summary":"Internship Analyst Investment Banking opportunity with BMO Capital Markets in Toronto, ON focused on Debt Capital Markets.","description_text":"Application Deadline: 10/18/2026 Address: 100 King Street West Job Family Group: Capital Mrkts Sales & Service BMO Capital Markets BMO Capital Markets is a leading, full-service North American-based financial services provider offering equity and debt underwriting, corporate lending and project financing, merger and acquisitions advisory services, securitization, treasury management, market risk management, debt and equity research and institutional sales and trading. BMO Capital Markets has over 2,700 professionals in 30+ locations around the world, including 20 offices in North America. BMO Capital Markets is a member of BMO Financial Group (NYSE, TSX: BMO), one of the largest diversified financial services providers in North America with US$1.1 trillion total assets and approximately 53,000 employees as of April 30, 2026. Investment Banking Overview: The Sophomore Summer Analyst program is designed for candidates in their second year of their undergraduate program. The Program provides participants a practical experience in a dynamic capital markets environment. Summer analysts are assigned to the Infrastructure Debt Capital Markets group from May to August. In addition to this on-the-job experience, analysts will participate in a one-week training and orientation program. Throughout the summer, the program includes the opportunity to network with bankers across all levels as well as learn about the culture of BMO Capital Markets, participate in learning and development sessions, and obtain career guidance from dedicated mentors. Infrastructure Capital Markets Overview: Advises public and private sector clients across North America on debt structuring and debt capital markets financing access for sectors primarily including infrastructure, power, energy, and transportation Serves a diverse client base, including utilities, infrastructure developers, pension funds, private equity sponsors, and government agencies Supports project finance transactions across power, energy, public-private partnerships (P3), and general infrastructure projects, as well as certain U.S. corporate style private placements Provides financial modeling, debt advisory, ratings advisory, bond underwriting, private placement, and capital markets execution services Engages with a broad range of stakeholders, including sponsors, investors, lenders, credit rating agencies, and internal product partners Responsibilities: As an Investment Banking Summer Analyst in the BMO Infrastructure Debt Capital Markets group, you will gain valuable exposure to debt advisory and debt capital raising services for infrastructure, project finance, renewable power, energy, and P3 sector clients. Specific responsibilities include: Maintain a current understanding of infrastructure project pipeline and debt capital markets Update project finance and debt capital market databases Support Bloomberg-related tasks and data requests Assist on written presentations, RFP write-ups, and pitch material for clients Assist on financial analysis for client coverage activities and internal updates on debt capital markets Work with other investment banking product and industry coverage group on transactions involving infrastructure, project finance, or investment grade debt issuances Participate in deal teams to develop, present, and win mandates for new opportunities Performing other tasks supporting client relationships and business development What’s in it for you: Summer Analysts start the internship by completing a one-week training and orientation program. From May to August, you will be working in Infrastructure Debt Capital Markets. In addition to on-the-job experience in your assigned business group, you will participate in professional development sessions and events throughout the summer. Beyond the on-the-job experience, you will have opportunities to network across various business groups, learn about BMO Capital Markets culture, participate in learning seminars, get feedback, and receive coaching and career guidance from mentors while broadening your skills. Eligibility criteria: You are available to work full-time from May-August 2027 Demonstrated leadership attributes in work, school or community Excellent analytic, critical thinking and problem-solving skills Strong interpersonal skills used within a demanding team environment Demonstrated proactivity, resiliency, and an unfailingly positive attitude Excellent capacity to independently function as part of a team through self-motivation Strong work ethic and a high level of professional integrity Demonstrated interest in working in capital markets and/or infrastructure role You are a student at an accredited University, currently enrolled in an undergraduate program with a graduation date of December 2028 or Spring 2029 Proven track record of excellent academic standing, extra curricular participation and demonstrated interest in finance You are a Canadian citizen, permanent resident of Canada, or an individual who is legally authorized to work in Canada and will not require sponsorship in the future Application requirements: Please submit the following three items as a single PDF file online application. One-page resume Cover letter (optional) Transcript Please note the target salary range for this specific position in Toronto is $95,000. This is a planned recruitment for future vacancies. This is a planned recruitment for future vacancies . Salary : Pay Type: Salaried The above represents BMO Financial Group’s pay range and type. Salaries will vary based on factors such as location, skills, experience, education, and qualifications for the role, and may include a commission structure. Salaries for part-time roles will be pro-rated based on number of hours regularly worked. For commission roles, the salary listed above represents BMO Financial Group’s expected target for the first year in this position. BMO Financial Group’s total compensation package will vary based on the pay type of the position and may include performance-based incentives, discretionary bonuses, as well as other perks and rewards. BMO also offers health insurance, tuition reimbursement, accident and life insurance, and retirement savings plans. To view more details of our benefits, please visit: https://jobs.bmo.com/global/en/Total-Rewards About Us At BMO we are driven by a shared Purpose: Boldly Grow the Good in business and life. It calls on us to create lasting, positive change for our customers, our communities and our people. By working together, innovating and pushing boundaries, we transform lives and businesses, and power economic growth around the world. As a member of the BMO team you are valued, respected and heard, and you have more ways to grow and make an impact. We strive to help you make an impact from day one – for yourself and our customers. We’ll support you with the tools and resources you need to reach new milestones, as you help our customers reach theirs. From in-depth training and coaching, to manager support and network-building opportunities, we’ll help you gain valuable experience, and broaden your skillset. To find out more visit us at https://jobs.bmo.com/ca/en . BMO is committed to an inclusive, equitable and accessible workplace. By learning from each other’s differences, we gain strength through our people and our perspectives. Accommodations are available on request for candidates taking part in all aspects of the selection process. To request accommodation, please contact your recruiter. Note to Recruiters: BMO does not accept unsolicited resumes from any source other than directly from a candidate. Any unsolicited resumes sent to BMO, directly or indirectly, will be considered BMO property. BMO will not pay a fee for any placement resulting from the receipt of an unsolicited resume. A recruiting agency must first have a valid, written and fully executed agency agreement contract for service to submit resumes.","description_status":"verified","description_verified_at":"2026-10-15T16:01:38.703Z","source_record_id":"bmo:R260028848","data_quality_notes":"Role-specific Investment Banking evidence found in title.","last_verified_at":"2026-10-15T16:01:38.703Z","updated_at":"2026-10-15T16:01:38.703Z"},{"external_job_id":"34293","company_id":"kpmg-cf","company_name":"KPMG Corporate Finance","title":"Senior Associate, Restructuring & Turnaround - Advisory","location_display":"Toronto, ON","city":"Toronto","province":"ON","country":"Canada","workplace_type":null,"category":"Investment Banking","specialization":"Restructuring","seniority":"Associate","employment_type":"FULL_TIME","program_type":null,"term_start":null,"term_end":null,"term_length_months":null,"date_posted":"2026-10-13","application_deadline":null,"salary_min":69000,"salary_max":107000,"salary_currency":"CAD","salary_period":"year","application_url":"https://careers.kpmg.ca/jobs/34293?lang=en-us","source_url":"https://careers.kpmg.ca/jobs/34293?lang=en-us","source_name":"KPMG Corporate Finance public careers site","status":"active","summary":"Associate Investment Banking opportunity with KPMG Corporate Finance in Toronto, ON focused on Restructuring.","description_text":"Overview At KPMG in Canada, our people bring their unique perspectives to Canada’s most important challenges. Here, you can build momentum that reaches beyond our business, develop skills for the future, and take ownership of your career with support at every stage. Join a firm where your career can make a difference. KPMG’s Turnaround & Restructuring practice helps companies and/or its stakeholders that are facing challenges and uncertainty, for a variety of reasons, including business underperformance, an imminent liquidity crisis and/or an inability to raise new capital. When companies have these challenges, our team provides financial advisory services to lenders, management, boards of directors, regulators, and other key stakeholders. Our professionals provide advisory services to help stakeholders navigate financial challenges and/or special situations. By applying strategic business and financial expertise, we assist organizations to overcome the changing business environments and the challenges they face. We also provide formal insolvency expertise, including acting as trustees under the Bankruptcy and Insolvency Act (BIA) and as a monitor under the Companies' Creditors Arrangement Act (CCAA). Learn more about Turnaround and Restructuring - KPMG Canada and exploare careers in Deal Advisory here. Are you a talented individual with a proven track record on executing project deliverables. Our Turnaround & Restructuring, Deal Advisory team in Toronto is looking for a professional like you with the skills and drive to make a real difference. As Senior Associate, you are a motivated, self-starter with expertise in finance, strategy, research, and business operations along with being deal focused. Our work environment is conducive to advancement for candidates who perform. We reward exceptional individuals with responsibility, profile, and career progression. Our practice is pre-approved for the CPA program. What you will do We are looking to fill two Senior Associate roles to support: 1. Working capital advisory 2. Debt advisory. Participate in developing restructuring strategies and plans Conduct financial analysis of companies in a variety of industries, including review of operations and forecasts Develop complex financial models and cash flow forecasts Perform market research and data analytics, financial due diligence, and independent business reviews of underperforming companies Prepare dashboards, slide decks and other advisory presentations to key stakeholders Assist with formal insolvency filings which may include securing assets and preparing court reports Communicate directly with a variety of stakeholders, including our clients, lenders, employees, creditors, and the advisors to stakeholders Assist with proactive business development initiatives What you bring to the role Completed, or working towards a professional designation (i.e., CPA/CA, CBV, CFA) Ability to prepare detailed, functional financial models, including financial projections Knowledge of the restructuring and insolvency industry. Strong consideration will be given to candidates with restructuring and insolvency experience Inquisitiveness with strong technical, investigative and computer skills (particularly, manipulating data and modeling in Excel) A committed, flexible approach to evolving priorities in a fast-paced intensive work environment Interest in registering for the Chartered Insolvency and Restructuring Professional (CIRP) qualification program Flexibility for mobility for out-of-town assignments The expected base salary range for this position is $69000 to $107000 and may be eligible for bonus awards. The determination of an applicant’s base salary within this range is based on the individual’s location, skills & competencies, and unique qualifications. In addition, KPMG offers a comprehensive and competitive Total Rewards program. Providing you with the support you need to be at your best Our Values, The KPMG Way Integrity, we do what is right | Excellence, we never stop learning and improving | Courage, we think and act boldly | Together, we respect each other and draw strength from our differences | For Better, we do what matters KPMG in Canada is a proud equal opportunities employer and we are committed to creating a respectful, inclusive and barrier-free workplace that allows all of our people to reach their full potential. A diverse workforce is key to our success and we believe in bringing your whole self to work. We welcome all qualified candidates to apply and hope you will choose KPMG in Canada as your employer of choice. Adjustments and accommodations throughout the recruitment process At KPMG, we are committed to fostering an inclusive recruitment process where all candidates can be themselves and excel. We aim to provide a positive experience and are prepared to offer adjustments or accommodations to help you perform at your best. Adjustments (informal requests), such as extra preparation time or the option for micro breaks during interviews, and accommodations (formal requests), such as accessible communication supports or technology aids, are tailored to individual needs and role requirements. You will have an opportunity to request an adjustment or accommodation at any point throughout the recruitment process. If you require support, please contact KPMG’s Employee Relations Service team by calling 1-888-466-4778. AI Usage We embrace the use of artificial intelligence (AI) to enhance the candidate experience and streamline our recruitment processes. AI tools may help with organizing applications or surfacing relevant qualifications. However, no hiring decisions are made using AI. Every hiring decision is made by our hiring managers and recruitment professionals, who are equipped with training that empowers them to use these tools responsibly. AI technologies used in our recruitment process undergo detailed risk assessments, including security and privacy requirements, that align with KPMG’s Trusted AI framework. We believe technology should empower human judgment, not replace it. It’s one of the many ways we’re delivering on our vision of being a technology-first, people-driven firm.","description_status":"verified","description_verified_at":"2026-10-15T16:01:38.703Z","source_record_id":"kpmg-cf:34293","data_quality_notes":"Role-specific Investment Banking evidence found in title.","last_verified_at":"2026-10-15T16:01:38.703Z","updated_at":"2026-10-15T16:01:38.703Z"},{"external_job_id":"JR100934","company_id":"aimco","company_name":"AIMCo","title":"Managing Director, Head of External Partnerships, Public Equities","location_display":"Calgary, AB","city":"Calgary","province":"AB","country":"Canada","workplace_type":null,"category":"Institutional Investing","specialization":"Public Equities","seniority":"Executive / Group Head","employment_type":"Full-time","program_type":"Full-time","term_start":null,"term_end":null,"term_length_months":null,"date_posted":"2026-10-05","application_deadline":"2026-10-27","salary_min":null,"salary_max":null,"salary_currency":null,"salary_period":null,"application_url":"https://aimco.wd10.myworkdayjobs.com/AIMCoCareers/job/Calgary/Managing-Director--Head-of-External-Partnerships--Public-Equities_JR100934","source_url":"https://aimco.wd10.myworkdayjobs.com/AIMCoCareers/job/Calgary/Managing-Director--Head-of-External-Partnerships--Public-Equities_JR100934","source_name":"AIMCo public careers site","status":"active","summary":"Executive / Group Head Institutional Investing opportunity with AIMCo in Calgary, AB focused on Public Equities.","description_text":"CLOSING DATE: October 27, 2026 Opportunity AIMCo’s Public Equities team is seeking a Managing Director, Head of External Partnerships to lead our externally managed investment strategies. External Partnerships is a key component of the Public Equities platform, complementing AIMCo’s internally managed active equity strategies in delivering against shared risk and return objectives. The mandate spans globally deployed equity and absolute return strategies, with a focus on identifying high-quality external managers and determining where external strategies can enhance the overall portfolio. Working closely with the Global Head of Public Equities, the Managing Director will provide strategic leadership across external manager selection and underwriting, portfolio construction, capital allocation, commercial negotiations and ongoing oversight, while leading and developing the External Partnerships team. ** This role will close at 11:59 pm MST on October 26, 2026** Key Responsibilities Investment Management & Portfolio Construction Lead the sourcing, evaluation, underwriting and ongoing oversight of external managers across equity and absolute return strategies. Oversee portfolio construction and capital allocation, ensuring external strategies contribute effectively to Public Equities’ overall risk and return objectives. Evaluate investment strategies, performance, risk exposures and sources of investment edge using rigorous quantitative and qualitative analysis. Lead recommendations related to manager selection, sizing, redemption and termination. Assess external strategies in the context of AIMCo’s internally managed exposures and broader portfolio objectives. Commercial & Relationship Management Lead negotiations related to investment management agreements, fee structures, commercial terms and governance arrangements. Build and maintain relationships with leading external managers and investment partners globally. Represent AIMCo with external managers, industry peers, clients and other stakeholders. Leadership & Collaboration Lead and develop a high-performing team of investment professionals, fostering a culture of collaboration, intellectual curiosity and accountability. Partner closely with Public Equities leadership and internal investment teams to share market intelligence, manager insights and investment perspectives. Contribute to the strategic direction and continued evolution of AIMCo’s Public Equities platform. Partner effectively across AIMCo to support strong investment governance and client outcomes. Qualifications Minimum of 15 years of institutional asset management experience, with significant experience selecting, underwriting and overseeing external investment managers. Deep expertise across externally managed equity strategies, including long-only and short-extension strategies, as well as absolute return strategies. Strong understanding of hedge fund and equity investment approaches, including their underlying risk and return drivers. Demonstrated track record of manager selection, sizing, capital allocation and termination decisions. Strong quantitative capabilities applied to manager evaluation, portfolio construction and investment risk management. Significant experience negotiating investment management fees, commercial terms and governance arrangements. Demonstrated experience leading and developing investment professionals. Strong academic background; CFA, CAIA, MBA or another relevant professional designation or advanced degree is strongly preferred. Ability and willingness to travel internationally as required. This role is based in Calgary, Alberta. Key Skills & Competencies Exceptional investment judgment and analytical capability. Strategic and commercially minded approach to investment decision-making. Strong negotiation and relationship management skills. Executive presence with the ability to represent AIMCo effectively with sophisticated external partners and senior stakeholders. Collaborative leadership style and ability to influence across investment teams. Ability to exercise sound judgment and make timely decisions in complex investment environments. High degree of integrity, accountability and professionalism. Next Steps We are excited to meet you. Please submit your resume or CV to be considered for this opportunity. Applications are being reviewed on a rolling basis and we will be in touch with any questions. Final candidates will be asked to undergo a security screening, which includes a credit bureau and a criminal record investigation, the results of which must be acceptable to AIMCo. ALERT - Be on the lookout for AIMCo career opportunities advertised through third parties that request an application fee or too much information. To verify, all opportunities are posted on aimco.ca/jobs At AIMCo, we draw upon the differences in who we are, where we come from and the way we think to deliver results for the Albertans who rely on us. We offer an inclusive, modern workplace where well-being is prioritized, and colleagues are enabled to do their best work. Our team members are motivated by our purpose and committed to creating long-term value for our clients and their beneficiaries.","description_status":"verified","description_verified_at":"2026-10-15T16:01:38.703Z","source_record_id":"aimco:JR100934","data_quality_notes":"Description establishes direct investment research, underwriting, execution, selection, allocation or portfolio-management responsibility.","last_verified_at":"2026-10-15T16:01:38.703Z","updated_at":"2026-10-15T16:01:38.703Z"}]$jobs$::jsonb)
  AS job(
